/// The bundled games library (SLAVNE_PARTIE_PLAN §3): shelves point into
/// PGN packs by (pack, index), so the UI lists games without parsing PGN.
/// Generated by tool/games/build.dart; format in docs/games_schema.md.
library;

/// Layout of a shelf in the hall.
enum ShelfKind { board, timeline, people }

class ShelfRef {
  const ShelfRef(this.id, this.kind, this.file);
  final String id;
  final ShelfKind kind;

  /// Path under assets/games/.
  final String file;
}

List<ShelfRef> parseLibraryIndex(Map<String, dynamic> j) => [
  for (final s in (j['shelves'] as List).cast<Map<String, dynamic>>())
    ShelfRef(s['id'] as String, ShelfKind.values.byName(s['kind'] as String), s['file'] as String),
];

/// One game on a shelf: enough to draw a tile and find the game.
class LibraryEntry {
  const LibraryEntry({
    required this.id,
    required this.pack,
    required this.index,
    required this.white,
    required this.black,
    required this.result,
    required this.moves,
    this.year,
    this.mate = false,
    this.round,
    this.tiebreak = false,
  });

  factory LibraryEntry.fromJson(Map<String, dynamic> j) => LibraryEntry(
    id: j['id'] as String,
    pack: j['p'] as String,
    index: j['i'] as int,
    white: j['w'] as String,
    black: j['b'] as String,
    result: j['r'] as String,
    moves: j['n'] as int,
    year: j['y'] as int?,
    mate: j['m'] == 1,
    round: j['rd'] as String?,
    tiebreak: j['tb'] == 1,
  );

  final String id;
  final String pack;
  final int index;
  final String white;
  final String black;

  /// PGN result: 1-0, 0-1, 1/2-1/2.
  final String result;

  /// Full moves.
  final int moves;
  final int? year;
  final bool mate;
  final String? round;
  final bool tiebreak;

  /// Game number inside a match ("4.1" → 4), or null.
  int? get roundNumber => int.tryParse((round ?? '').split('.').first);
}

class MatchScore {
  const MatchScore(this.name, this.points);
  final String name;
  final double points;
}

/// A match, a tournament, a champion or the golden board.
class LibraryGroup {
  const LibraryGroup({
    required this.id,
    required this.entries,
    this.title,
    this.line,
    this.kind,
    this.year,
    this.score = const [],
    this.number,
    this.reigns = const [],
  });

  factory LibraryGroup.fromJson(Map<String, dynamic> j) => LibraryGroup(
    id: j['id'] as String,
    title: j['title'] as String?,
    line: j['line'] as String?,
    kind: j['kind'] as String?,
    year: j['year'] as int?,
    number: j['n'] as int?,
    reigns: [for (final r in j['reigns'] as List? ?? const []) r as String],
    score: [for (final s in (j['score'] as List? ?? const []).cast<Map<String, dynamic>>()) MatchScore(s['name'] as String, (s['pts'] as num).toDouble())],
    entries: [for (final e in (j['items'] as List).cast<Map<String, dynamic>>()) LibraryEntry.fromJson(e)],
  );

  final String id;

  /// Match title ("Steinitz – Zukertort") or a champion's name. Player and
  /// place names are the same in every language (PLAN §5).
  final String? title;

  /// classic or fide (title matches).
  final String? line;

  /// match or tournament (title matches).
  final String? kind;
  final int? year;

  /// Main games only, title holder first.
  final List<MatchScore> score;

  /// Women's champion number.
  final int? number;

  /// "1962–1978".
  final List<String> reigns;
  final List<LibraryEntry> entries;
}

List<LibraryGroup> parseCollection(Map<String, dynamic> j) => [for (final g in (j['groups'] as List).cast<Map<String, dynamic>>()) LibraryGroup.fromJson(g)];

/// "12½" — points as a child-friendly score.
String formatPoints(double p) {
  final whole = p.floor();
  final half = p - whole >= .5;
  if (!half) return '$whole';
  return whole == 0 ? '½' : '$whole½';
}
